pub(crate) fn merge_coherence_ratios(results: &Vec<CoherenceMatches>) -> CoherenceMatches {
    let mut per_language_ratios: Vec<(&'static Language, Vec<f32>)> = Vec::new();

    for result in results {
        for sub_result in result {
            if let Some((_, ratios)) = per_language_ratios
                .iter_mut()
                .find(|(language, _)| std::ptr::eq(*language, sub_result.language))
            {
                ratios.push(sub_result.score);
            } else {
                per_language_ratios.push((sub_result.language, vec![sub_result.score]));
            }
        }
    }

    let mut merged: CoherenceMatches = per_language_ratios
        .into_iter()
        .map(|(language, ratios)| {
            let average = ratios.iter().sum::<f32>() / ratios.len() as f32;
            CoherenceMatch {
                language,
                score: (average * 10000.0).round() / 10000.0,
            }
        })
        .collect();

    merged.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(Ordering::Equal));
    merged
}

async fn list_namespaces(
    &self,
    parent: Option<&NamespaceIdent>,
) -> Result<Vec<NamespaceIdent>> {
    let mut url = Url::parse(&self.namespaces_endpoint()).map_err(|e| {
        Error::new(ErrorKind::Unexpected, "Failed to parse namespaces endpoint!").with_source(e)
    })?;

    let parent_names = parent.map(|p| p.as_ref().to_vec()).unwrap_or_default();

    if !parent_names.is_empty() {
        url.query_pairs_mut()
            .append_pair("parent", &parent_names.iter().map(|s| encode(s)).join("\u{1f}"));
    }

    let request = self.client.0.get(url).build()?;
    let response = self
        .client
        .query::<ListNamespaceResponse, ErrorResponse, OK>(request)
        .await?;

    response
        .namespaces
        .into_iter()
        .map(|child_namespace| {
            let mut namespace = parent_names.clone();
            namespace.extend(child_namespace);
            NamespaceIdent::from_vec(namespace)
        })
        .collect()
}

fn not_starts_with(
    &mut self,
    reference: &BoundReference,
    datum: &Datum,
    _predicate: &BoundPredicate,
) -> crate::Result<bool> {
    let field = reference.field();
    let field_id = field.id;

    if self.contains_nulls_only(field_id) {
        return ROWS_MIGHT_MATCH;
    }

    if !matches!(field.field_type.as_ref(), Type::Primitive(_)) {
        return Err(Error::new(
            ErrorKind::Unexpected,
            format!("Expected PrimitiveType: {:?}", field.field_type),
        ));
    }

    let prefix = datum.to_string();
    let len_prefix = prefix.len();

    if let (Some(lower_bound), Some(upper_bound)) =
        (self.lower_bound(field_id), self.upper_bound(field_id))
    {
        let lower_bound = lower_bound.to_string();
        let upper_bound = upper_bound.to_string();

        if lower_bound.len() < len_prefix {
            return ROWS_MIGHT_MATCH;
        }

        if lower_bound[..len_prefix] == prefix {
            if upper_bound.len() < len_prefix {
                return ROWS_MIGHT_MATCH;
            }

            if upper_bound[..len_prefix] == prefix {
                return ROWS_CANNOT_MATCH;
            }
        }
    }

    ROWS_MIGHT_MATCH
}

