fn map(
        &mut self,
        map: &MapType,
        key_value: AvroSchemaOrField,
        value: AvroSchemaOrField,
    ) -> Result<AvroSchemaOrField> {
        let key_field_schema = key_value.unwrap_left();
        let value_field_schema = value.unwrap_left();

        if matches!(key_field_schema, AvroSchema::String) {
            // Avro Maps does not support other keys than a String
            Ok(Either::Left(AvroSchema::Map(Box::new(value_field_schema))))
        } else {
            // Creates a logical map that's a list of records, which is binary compatible
            let key_field = AvroRecordField {
                name: "key".to_string(),
                doc: None,
                aliases: None,
                default: None,
                schema: key_field_schema,
                order: RecordFieldOrder::Ignore,
                position: 0,
                custom_attributes: BTreeMap::from([(
                    "field-id".to_string(),
                    Value::Number(Number::from(map.key_field.id)),
                )]),
            };

            let value_field = AvroRecordField {
                name: "value".to_string(),
                doc: None,
                aliases: None,
                default: None,
                schema: value_field_schema,
                order: RecordFieldOrder::Ignore,
                position: 1,
                custom_attributes: BTreeMap::from([(
                    "field-id".to_string(),
                    Value::Number(Number::from(map.value_field.id)),
                )]),
            };

            let record_name = format!("k{}_v{}", map.key_field.id, map.value_field.id);
            let record_schema =
                avro_record_schema(record_name.as_str(), vec![key_field, value_field])?;

            Ok(Either::Left(AvroSchema::Array(Box::new(record_schema))))
        }
    }

